import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, Chrome, UserPlus, ShieldCheck, Globe, Loader2 } from 'lucide-react';

const Home = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const navigate = useNavigate();

  // Replace this with your actual Client ID from Google Console
  const GOOGLE_CLIENT_ID = "245690543736-8apb2t2avog9ee188so4ijp3u1ujf59m.apps.googleusercontent.com";

  const bgImage = "https://images.unsplash.com/photo-1497215728101-856f4ea42174?auto=format&fit=crop&q=80&w=2070";

  // Load Google Identity Services Script on Mount
  useEffect(() => {
    const script = document.createElement("script");
    script.src = "https://accounts.google.com/gsi/client";
    script.async = true;
    script.defer = true;
    document.body.appendChild(script);
  }, []);

  // Manual Login Handler
  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoggingIn(true);

    try {
      const res = await fetch("http://localhost:5000/api/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          email: email,
          password: password
        })
      });

      const data = await res.json();

      if (res.ok) {
        alert("Login Successful ✅");

        // ✅ Save token (if backend sends JWT)
        if (data.token) {
          localStorage.setItem("token", data.token);
        }

        // ✅ Redirect based on role
        if (data.role === "student") {
          navigate("/candidate/dashboard");
        } else if (data.role === "hr") {
          navigate("/hr/dashboard");
        } else if (data.role === "admin") {
          navigate("/admin/dashboard");
        } else {
          navigate("/"); // fallback
        }

      } else {
        alert(data.message || "Invalid Credentials ❌");
      }

    } catch (error) {
      console.error("Login Error:", error);
      alert("Server not running or connection error ❌");
    } finally {
      setIsLoggingIn(false);
    }
  };
  // GOOGLE LOGIN TRIGGER - This opens the "Choose Account" Popup
  const handleGoogleLogin = () => {
    if (!window.google) {
      alert("Google Identity Services not loaded. Please refresh the page.");
      return;
    }

    // Initialize the Token Client
    const client = window.google.accounts.oauth2.initTokenClient({
      client_id: GOOGLE_CLIENT_ID,
      scope: 'openid email profile', // Request basic user info
      callback: (tokenResponse) => {
        if (tokenResponse && tokenResponse.access_token) {
          console.log("Google Auth Success. Token:", tokenResponse.access_token);
          setIsLoggingIn(true);
          // Redirect to Admin Dashboard
          setTimeout(() => navigate("/admin"), 1000);
        }
      },
      error_callback: (error) => {
        console.error("Google Auth Error:", error);
        alert("Google Login failed.");
      }
    });

    // Request the popup window immediately
    client.requestAccessToken({ prompt: 'select_account' });
  };

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-center relative font-sans overflow-hidden"
      style={{ 
        backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.8), rgba(88, 28, 135, 0.7)), url(${bgImage})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center'
      }}
    >
      {/* Visual Decor */}
      <div className="absolute -top-24 -left-24 w-96 h-96 bg-purple-500/20 rounded-full blur-3xl"></div>
      <div className="absolute -bottom-24 -right-24 w-96 h-96 bg-blue-500/20 rounded-full blur-3xl"></div>

      {/* Navigation to Register */}
      <div className="absolute top-8 right-8 z-20">
        <button 
          onClick={() => navigate('/register')}
          className="flex items-center gap-2 bg-white/10 backdrop-blur-md text-white border border-white/20 px-6 py-2.5 rounded-full font-bold hover:bg-white hover:text-purple-700 transition-all shadow-xl active:scale-95"
        >
          <UserPlus size={18} /> Join Us
        </button>
      </div>

      <div className="z-10 w-full max-w-md px-4 animate-in fade-in zoom-in duration-500">
        <div className="bg-white/10 backdrop-blur-2xl p-10 rounded-[3rem] shadow-2xl border border-white/20">
          
          {/* Header */}
          <div className="text-center mb-10">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-tr from-purple-500 to-blue-500 rounded-3xl shadow-lg mb-4 transform -rotate-12 hover:rotate-0 transition-transform duration-300">
              <Globe className="text-white" size={40} />
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter">
              Talent <span className="text-purple-400">Pool</span>
            </h1>
            <p className="text-gray-300 text-sm mt-2 font-medium tracking-wide">Enterprise Auth Portal</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-purple-300 uppercase tracking-widest ml-2">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-4 top-4 text-gray-400" size={20} />
                <input 
                  type="email" 
                  placeholder="admin@talentpool.com"
                  className="input-style"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-purple-300 uppercase tracking-widest ml-2">Password</label>
              <div className="relative">
                <Lock className="absolute left-4 top-4 text-gray-400" size={20} />
                <input 
                  type="password" 
                  placeholder="••••••••"
                  className="input-style"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={isLoggingIn}
              className="w-full bg-gradient-to-r from-indigo-600 to-purple-600 hover:brightness-110 text-white font-black py-4 rounded-2xl shadow-xl transition-all transform active:scale-95 flex items-center justify-center gap-2 tracking-widest"
            >
              {isLoggingIn ? <Loader2 className="animate-spin" size={20} /> : 'SIGN IN'}
            </button>
          </form>

          <div className="flex items-center my-8">
            <div className="flex-grow border-t border-white/10"></div>
            <span className="px-4 text-gray-500 text-[10px] font-black uppercase tracking-[0.2em]">OAuth 2.0 Secure</span>
            <div className="flex-grow border-t border-white/10"></div>
          </div>

          {/* GOOGLE BUTTON - ACTIVE TRIGGER */}
          <button 
            type="button"
            onClick={handleGoogleLogin}
            className="w-full flex items-center justify-center gap-3 border border-white/10 py-4 rounded-2xl hover:bg-white/10 transition-all text-white font-bold bg-white/5 shadow-sm active:scale-95"
          >
            <Chrome size={20} className="text-red-400" />
            Continue with Google
          </button>
        </div>
      </div>

      <div className="mt-8 flex items-center gap-2 text-gray-400 text-xs font-bold uppercase tracking-widest opacity-60">
        <ShieldCheck size={14} /> Certified Secure Authentication
      </div>

      <style>{`
        .input-style {
          width: 100%; pl: 3rem; padding-left: 3rem; padding-right: 1rem; padding-top: 1rem; padding-bottom: 1rem;
          background-color: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.1);
          border-radius: 1.25rem; color: white; outline: none; transition: all 0.3s;
        }
        .input-style:focus {
          border-color: #818cf8; box-shadow: 0 0 0 2px rgba(129, 140, 248, 0.3);
        }
      `}</style>
    </div>
  );
};

export default Home;
